/** Prove the simulated swap's actual debit before deriving a partial-fill budget.
 * The pool may move between the SDK quote and simulation. CPI records are bound
 * to the sole top-level swap and the already-verified frozen lookup snapshot. */
export function verifyAtomicGraduationSimulation(simulation,transaction,lookupTables,{trade,addresses:a,wallet,quoteDecimals}){
  const writable=[],readonly=[];
  for(const lookup of transaction.message.addressTableLookups){const table=lookupTables.find(row=>str(row.address||row.key)===str(lookup.accountKey));ensure(table&&Array.isArray(table.addresses),'The simulation lookup snapshot is unavailable.');for(const [indices,target] of [[lookup.writableIndexes,writable],[lookup.readonlyIndexes,readonly]])for(const index of indices){ensure(table.addresses[index],'The simulation lookup index is invalid.');target.push(pk(table.addresses[index]));}}
  const keys=transaction.message.getAccountKeys({accountKeysFromLookups:{writable,readonly}}),key=index=>{ensure(Number.isInteger(index)&&index>=0&&keys.get(index),'The simulation instruction account is invalid.');return str(keys.get(index));};
  const swaps=transaction.message.compiledInstructions.map((ix,index)=>({ix,index})).filter(({ix})=>key(ix.programIdIndex)===str(a.dammProgram)&&Buffer.from(ix.data).subarray(0,8).equals(DAMM_SWAP));ensure(swaps.length===1,'The reviewed atomic transaction must contain one DAMM swap.');
  const groups=simulation.innerInstructions?.filter(group=>group.index===swaps[0].index);ensure(groups?.length===1&&Array.isArray(groups[0].instructions),'The RPC omitted the atomic swap simulation proof.');
  const transfers=[];
  for(const ix of groups[0].instructions){
    const program=ix.programId===undefined?key(ix.programIdIndex):str(ix.programId);if(![str(TOKEN_PROGRAM_ID),str(a.quoteTokenProgram)].includes(program))continue;
    if(ix.parsed){const {type,info}=ix.parsed;if(!['transfer','transferChecked'].includes(type))continue;const checked=type==='transferChecked',raw=checked?info?.tokenAmount?.amount:info?.amount;ensure(info&&typeof raw==='string'&&/^(0|[1-9]\d*)$/.test(raw),'The parsed simulated token transfer is incomplete.');transfers.push({program,source:info.source,destination:info.destination,authority:info.authority,mint:checked?info.mint:null,decimals:checked?info.tokenAmount.decimals:null,amount:BigInt(raw)});continue;}
    ensure(typeof ix.data==='string'&&Array.isArray(ix.accounts),'The simulated token instruction is incomplete.');const data=Buffer.from(bs58.decode(ix.data));if(![3,12].includes(data[0]))continue;const checked=data[0]===12,account=index=>typeof ix.accounts[index]==='number'?key(ix.accounts[index]):str(pk(ix.accounts[index]));ensure(data.length===(checked?10:9)&&ix.accounts.length>=(checked?4:3),'The simulated token transfer is malformed.');transfers.push({program,source:account(0),destination:account(checked?2:1),authority:account(checked?3:2),mint:checked?account(1):null,decimals:checked?data[9]:null,amount:data.readBigUInt64LE(1)});
  }
  const quote=transfers.filter(t=>t.source===trade.quoteAccount&&t.destination===str(a.dammQuoteVault)),base=transfers.filter(t=>t.source===str(a.dammBaseVault)&&t.destination===str(a.userAta));
  ensure(quote.length===1&&quote[0].program===str(a.quoteTokenProgram)&&quote[0].authority===wallet&&(!quote[0].mint||quote[0].mint===str(a.quoteMint)&&quote[0].decimals===quoteDecimals)&&quote[0].amount>0n&&quote[0].amount<=BigInt(trade.input),'The simulation does not prove the reviewed quote debit.');
  ensure(base.length===1&&base[0].program===str(TOKEN_PROGRAM_ID)&&base[0].authority===str(a.dammAuthority)&&(!base[0].mint||base[0].mint===str(a.mint)&&base[0].decimals===6)&&base[0].amount>=BigInt(trade.minimum),'The simulation does not prove the minimum token receipt.');
  return {charged:quote[0].amount,output:base[0].amount};
}

export function inspectDammPumpQuote(mintAddress,account) {
  let evidence={compatibilityVerified:false};
  try {
    const mint=pk(mintAddress), program=account?.owner;
    ensure(account&&!account.executable&&[TOKEN_PROGRAM_ID,TOKEN_2022_PROGRAM_ID].some(p=>p.equals(program)),'This quote mint is unavailable.');
    const parsed=unpackMint(mint,account,program); ensure(parsed.isInitialized&&parsed.decimals<=18,'The quote decimals or initialization are unsupported.');
    const extensions=program.equals(TOKEN_2022_PROGRAM_ID)?getExtensionTypes(parsed.tlvData):[];
    for(let offset=0;offset<parsed.tlvData.length;){ensure(offset+4<=parsed.tlvData.length,'The quote mint layout is unsupported.');const length=parsed.tlvData.readUInt16LE(offset+2);ensure(offset+4+length<=parsed.tlvData.length,'The quote mint layout is unsupported.');offset+=4+length;}
    const metadata=new Set([ExtensionType.MetadataPointer,ExtensionType.TokenMetadata]);
    ensure(!program.equals(TOKEN_PROGRAM_ID)||account.data.length===82,'The quote mint layout is unsupported.');
    for(const type of extensions.filter(type=>metadata.has(type))){const data=getExtensionData(type,parsed.tlvData);ensure(type===ExtensionType.MetadataPointer?data?.length===64:data?.length>=80&&pk(data.subarray(32,64)).equals(mint),'The quote metadata extension does not match the reviewed mint layout.');}
    evidence={compatibilityVerified:true,tokenProgram:program.toBase58(),decimals:parsed.decimals,extensions};
    ensure(extensions.every(e=>metadata.has(e)),'This quote mint’s token extensions have not passed both DAMM and PumpSwap compatibility checks.');
    return {...evidence,ready:true,launchReady:true,supported:true,availability:'ready',comingSoon:false,reason:'',supportReason:'',mint:mint.toBase58()};
  } catch(e) { return {...evidence,ready:false,launchReady:false,supported:false,availability:evidence.compatibilityVerified?'coming-soon':'unavailable',comingSoon:evidence.compatibilityVerified,reason:e.message,supportReason:e.message,mint:String(mintAddress)}; }
}

